<div class="space-y-6"><header class="flex justify-between items-start"><div><?php if($profile['brand_logo_url']):?><img src="<?=htmlspecialchars($profile['brand_logo_url'])?>" alt="" class="h-10 mb-2"><?php endif?><h1 class="text-3xl font-bold"><?=htmlspecialchars($profile['brand_name']?:'Panel de revendedor')?></h1><p class="text-slate-400"><?=htmlspecialchars($profile['name'])?></p></div><form method="post" action="/reseller/logout"><?=$csrf->field()?><button class="bg-slate-800 px-4 py-2 rounded">Salir</button></form></header>
<section class="grid md:grid-cols-3 gap-4"><article class="bg-cyan-950 border border-cyan-800 rounded-xl p-5"><span class="text-cyan-300">Créditos</span><strong class="block text-4xl mt-2"><?=number_format((int)$profile['credit_balance'])?></strong></article><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><span class="text-slate-400">Cuentas</span><strong class="block text-4xl mt-2"><?=count($accounts)?><?=isset($profile['max_accounts'])&&$profile['max_accounts']!==null?' / '.(int)$profile['max_accounts']:''?></strong></article><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><span class="text-slate-400">Paquetes disponibles</span><strong class="block text-4xl mt-2"><?=count($packages)?></strong></article></section>
<section class="bg-slate-900 border border-slate-800 rounded-xl p-5"><h2 class="text-xl font-bold mb-4">Crear cuenta</h2><form method="post" action="/reseller/accounts" class="grid md:grid-cols-5 gap-3"><?=$csrf->field()?><input required name="username" placeholder="Usuario" class="bg-slate-800 rounded p-2"><input required minlength="8" type="password" name="password" placeholder="Credencial" class="bg-slate-800 rounded p-2"><input required min="1" type="number" name="max_connections" value="1" class="bg-slate-800 rounded p-2"><select required name="package_id" class="bg-slate-800 rounded p-2"><option value="">Paquete</option><?php foreach($packages as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?> — <?=$p['internal_price']?> créditos</option><?php endforeach?></select><button class="bg-cyan-600 rounded p-2">Crear</button></form></section>
<section><h2 class="text-xl font-bold mb-3">Mis cuentas</h2><div class="overflow-x-auto border border-slate-800 rounded-xl"><table class="w-full text-sm"><thead class="bg-slate-900"><tr><th class="p-3 text-left">Usuario</th><th>Estado</th><th>Expira</th><th>Conexiones</th><th>Acciones</th></tr></thead><tbody class="divide-y divide-slate-800"><?php foreach($accounts as $a):?><tr><td class="p-3"><?=htmlspecialchars($a['username'])?></td><td class="text-center"><?=htmlspecialchars($a['status'])?></td><td class="text-center"><?=htmlspecialchars($a['expires_at']??'—')?></td><td class="text-center"><?=$a['max_connections']?></td><td class="p-2"><div class="flex gap-2 justify-center"><form method="post" action="/reseller/accounts/renew"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$a['id']?>"><select name="package_id" class="bg-slate-800 p-1 rounded"><?php foreach($packages as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach?></select><button class="bg-emerald-700 px-2 py-1 rounded">Renovar</button></form><form method="post" action="/reseller/accounts/suspend"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$a['id']?>"><button class="bg-amber-700 px-2 py-1 rounded">Suspender</button></form></div></td></tr><?php endforeach?></tbody></table></div></section>
<section><h2 class="text-xl font-bold mb-3">Historial de créditos</h2><div class="grid gap-2"><?php foreach($movements as $m):?><article class="bg-slate-900 border border-slate-800 rounded p-3 flex justify-between"><div><strong class="<?=$m['amount']<0?'text-red-400':'text-emerald-400'?>"><?=$m['amount']>0?'+':''?><?=$m['amount']?></strong> <?=htmlspecialchars($m['reason'])?><div class="text-xs text-slate-500"><?=htmlspecialchars($m['uuid'])?> · <?=htmlspecialchars($m['ip']??'sin IP')?></div></div><div class="text-right"><?=$m['balance_before']?> → <?=$m['balance_after']?><div class="text-xs text-slate-500"><?=$m['created_at']?></div></div></article><?php endforeach?></div></section></div>
